#include <iostream>
#include <regex>
#include <string>

int main() {
  std::string text = "123-456-7890";
  std::regex pattern(R"(\d{3}-\d{3}-\d{4})" );
  std::smatch match;
  if (std::regex_match(text, match, pattern)) {
    std::cout << "Match!\n";
  } else {
    std::cout << "No match.\n";
  }
  return 0;
}
